beginning.embedded_functions:
//each function name should be prefixed by em_

// IANA Protocol Numbers registry, last updated 2026-03-09
// (https://www.iana.org/assignments/protocol-numbers/):
//   0-147   assigned (144 AGGFRAG, 145 NSH, 146 Homa, 147 BIT-EMU are the latest)
//   148-252 unassigned           => flagged
//   253-254 experimentation and testing (RFC 3692) => not flagged
//   255     reserved             => flagged
static inline int em_check_ip_proto_id(int i){
  if(i>=148 && i<=252) return 1;
  if (i==255) return 1;
  return 0;
}
